solution:
public static long SparseDot(int[][] left, int[][] right)
{
    var d = left.ToDictionary(r => r[0], r => r[1]); long total = 0; foreach (var r in right) if (d.TryGetValue(r[0], out int value)) total += (long)value * r[1]; return total;
}

