solution:
public static int[] Spiral(int[][] matrix)
{
    if (matrix.Length == 0 || matrix[0].Length == 0) return []; int top = 0, bottom = matrix.Length-1, left = 0, right = matrix[0].Length-1; var output = new List<int>(); while (top <= bottom && left <= right) { for (int j = left; j <= right; j++) output.Add(matrix[top][j]); top++; for (int i = top; i <= bottom; i++) output.Add(matrix[i][right]); right--; if (top <= bottom) { for (int j = right; j >= left; j--) output.Add(matrix[bottom][j]); bottom--; } if (left <= right) { for (int i = bottom; i >= top; i--) output.Add(matrix[i][left]); left++; } } return output.ToArray();
}

