}

solution:
public static long CountGridPaths(int[][] grid)
{
    if (grid.Length == 0 || grid[0].Length == 0) return 0; var dp = new long[grid[0].Length]; dp[0] = 1; foreach (var row in grid) for (int j = 0; j < row.Length; j++) { if (row[j] == 1) dp[j] = 0; else if (j > 0) dp[j] += dp[j-1]; } return dp[^1];
}

