{
    throw new NotImplementedException();
}

solution:
public static int EditDistance(string source, string target)
{
    var dp = new int[source.Length+1,target.Length+1]; for (int i = 0; i <= source.Length; i++) dp[i,0] = i; for (int j = 0; j <= target.Length; j++) dp[0,j] = j; for (int i = 1; i <= source.Length; i++) for (int j = 1; j <= target.Length; j++) dp[i,j] = Math.Min(Math.Min(dp[i-1,j]+1, dp[i,j-1]+1), dp[i-1,j-1]+(source[i-1] == target[j-1] ? 0 : 1)); return dp[source.Length,target.Length];
}

