{
    throw new NotImplementedException();
}

solution:
public static int IncreasingLength(int[] values)
{
    var dp = new int[values.Length]; int best = 0; for (int i = 0; i < values.Length; i++) { dp[i] = 1; for (int j = 0; j < i; j++) if (values[j] < values[i]) dp[i] = Math.Max(dp[i], dp[j]+1); best = Math.Max(best, dp[i]); } return best;
}

