{
    throw new NotImplementedException();
}

solution:
public static int ShortestTargetWindow(int[] values, long target)
{
    int left = 0, best = int.MaxValue; long sum = 0; for (int right = 0; right < values.Length; right++) { sum += values[right]; while (sum >= target) { best = Math.Min(best, right-left+1); sum -= values[left++]; } } return best == int.MaxValue ? 0 : best;
}

