solution:
public static long ExactTargetCount(int[] values, long target)
{
    var counts = new Dictionary<long,long> { [0] = 1 }; long prefix = 0, answer = 0; foreach (int x in values) { prefix += x; if (counts.TryGetValue(prefix-target, out long count)) answer += count; counts.TryGetValue(prefix, out long old); counts[prefix] = old+1; } return answer;
}

