public static long MaximumSegment(int[] values)
{
    if (values.Length == 0) return 0; long ending = values[0], best = ending; for (int i = 1; i < values.Length; i++) { ending = Math.Max((long)values[i], ending + values[i]); best = Math.Max(best, ending); } return best;
}

