public static int ComponentCount(int count, int[][] edges)
{
    throw new NotImplementedException();
}

solution:
public static int ComponentCount(int count, int[][] edges)
{
    var graph = Enumerable.Range(0, count).Select(_ => new List<int>()).ToArray(); foreach (var edge in edges) { graph[edge[0]].Add(edge[1]); graph[edge[1]].Add(edge[0]); } var seen = new bool[count]; int groups = 0; for (int s = 0; s < count; s++) { if (seen[s]) continue; groups++; var queue = new Queue<int>(); queue.Enqueue(s); seen[s] = true; while (queue.Count > 0) { int v = queue.Dequeue(); foreach (int u in graph[v]) if (!seen[u]) { seen[u] = true; queue.Enqueue(u); } } } return groups;
}

