    throw new NotImplementedException();
}

solution:
public static bool IsBipartite(int count, int[][] edges)
{
    var graph = Enumerable.Range(0, count).Select(_ => new List<int>()).ToArray(); foreach (var e in edges) { graph[e[0]].Add(e[1]); graph[e[1]].Add(e[0]); } var color = Enumerable.Repeat(-1, count).ToArray(); for (int s = 0; s < count; s++) { if (color[s] != -1) continue; color[s] = 0; var queue = new Queue<int>(); queue.Enqueue(s); while (queue.Count > 0) { int v = queue.Dequeue(); foreach (int u in graph[v]) { if (color[u] == -1) { color[u] = 1-color[v]; queue.Enqueue(u); } else if (color[u] == color[v]) return false; } } } return true;
}
